import pytest
from fastapi.testclient import TestClient

from app.main import app, store


@pytest.fixture
def client():
    store.clear()
    return TestClient(app)


@pytest.mark.parametrize("email", ["not-an-email", "missing-domain@", "@missing-local.com"])
def test_invalid_email_is_rejected(client, email):
    response = client.post("/register", json={"email": email, "password": "long-enough-1"})
    assert response.status_code == 422


